mapper.select:
select id , title , link , snippet , pub_date as pubDate , source from curated_items
order by pub_date ${sortDir}
order by pub_date desc
limit #{limit} offset #{offset}

select i.id , i.title , i.link , i.snippet , i.pub_date as pubDate , i.source , i.source_id as sourceId , i.created_at as createdAt from curated_items i
and i.source_id = #{sourceId}
order by i.pub_date ${sortDir}
order by i.created_at ${sortDir}
order by i.created_at desc
limit #{limit} offset #{offset}

select count(*)
from curated_items i


        and i.source_id = #{sourceId}
